def get_weather(city):
    return f"{city}:sunny"

def add(a, b):
    return a + b

REGISTRY = {"get_weather": get_weather, "add": add}

CALLS = [
    {"name": "get_weather", "args": {"city": "Chennai"}},
    {"name": "add", "args": {"a": 2, "b": 3}},
    {"name": "delete_db", "args": {}},
]

def dispatch(calls, registry):
    results = []
    for call in calls:
        name = call["name"]
        fn = registry.get(name)
        if fn is None:
            results.append(f"error: unknown tool {name}")
        else:
            results.append(str(fn(**call.get("args", {}))))
    return results

results = dispatch(CALLS, REGISTRY)
for line in results:
    print(line)
print(f"handled={len(CALLS)}")
